\begin{align*} 2^{606} + 1 & \equiv 2^{{\rm Rem} ( 606, \phi(5) )} + 1 \\ & \equiv 2^{{\rm Rem} ( 606, 4 )} + 1 \\ & \equiv 2^2 + 1 \\ & \equiv 0 . \end{align*}
